    elif r == 15:
        row = [2]*test_w
    test_in.append(row)

def transform_partner_v2(grid):
    h, w = len(grid), len(grid[0])

    # Find background color
    non_2_counts = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 2:
                non_2_counts[v] = non_2_counts.get(v, 0) + 1
    bg = max(non_2_counts, key=non_2_counts.get)

    # Find pattern cells (values not bg and not 2)
    pattern_val = None
    pattern_cells = []
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != bg and v != 2:
                pattern_val = v
                pattern_cells.append((r, c))

    # Build output - copy original
    output = [row[:] for row in grid]

    # Clear the pattern (set to bg)
    for (r, c) in pattern_cells:
        output[r][c] = bg

    # Place pattern at (r-1, c)
    for (r, c) in pattern_cells:
        new_r = r - 1
        if 0 <= new_r < h:
            output[new_r][c] = pattern_val

    # The row below the highest new pattern row becomes (bg-1)
    max_pattern_row = -1
    for r in range(h):
        for c in range(w):
            if output[r][c] == pattern_val:
                if r > max_pattern_row:
                    max_pattern_row = r

    if max_pattern_row < h - 1:
        # Fill row below with (bg-1)
        for c in range(w):
            output[max_pattern_row + 1][c] = bg - 1

    return output

test_out_pred = transform_partner_v2(test_in)
print("Predicted test output:")
for row in test_out_pred:
    print(' '.join(str(c) for c in row))

